import * as fs from 'fs';
import * as path from 'path';
import { expect, test as setup } from '@playwright/test';

const authFile = 'e2e/.auth/user.json';
const csrfFile = 'e2e/.auth/csrf.json';

/**
 * Authentication setup - runs once before all tests.
 */
setup('authenticate', async ({ page }) => {
	const authDir = path.dirname(authFile);
	if (!fs.existsSync(authDir)) {
		fs.mkdirSync(authDir, { recursive: true });
	}

	// Login via Frappe API
	const loginResponse = await page.request.post('/api/method/login', {
		form: {
			usr: process.env.FRAPPE_USER || 'Administrator',
			pwd: process.env.FRAPPE_PASSWORD || 'admin',
		},
	});
	expect(loginResponse.ok()).toBeTruthy();

	// Verify login
	const userResponse = await page.request.get(
		'/api/method/frappe.auth.get_logged_user',
	);
	expect(userResponse.ok()).toBeTruthy();
	const userData = await userResponse.json();
	expect(userData.message).not.toBe('Guest');
	console.log(`Authenticated as: ${userData.message}`);

	// Navigate to app to get CSRF token
	await page.goto('/app');
	await page.waitForLoadState('networkidle');

	const csrfToken = await page.evaluate(() => {
		return (window as unknown as { frappe?: { csrf_token?: string } }).frappe
			?.csrf_token;
	});

	if (csrfToken) {
		fs.writeFileSync(csrfFile, JSON.stringify({ csrf_token: csrfToken }));
	}

	await page.context().storageState({ path: authFile });
});

import type { Page } from '@playwright/test';
import { expect, test } from '../fixtures';
import type { WikiFactory } from '../helpers/factory';

const PULSE_CLIENT_URL = 'https://pulse.test/assets/pulse/js/pulse_client.js';

// Stands in for Pulse's CDN client so CI needs no network and can read back
// what the reader passed to it.
const STUB_CLIENT = `
export class PulseClient {
	constructor(options) {
		window.pulseOptions = options;
		window.pulseEvents = [];
	}
	capture(event, app, props) {
		window.pulseEvents.push({ event, app, props });
	}
}
`;

declare global {
	const readerTelemetry: Record<string, unknown>;
	interface Window {
		pulseOptions?: Record<string, unknown>;
		pulseEvents?: {
			event: string;
			app: string;
			props: Record<string, unknown>;
		}[];
	}
}

async function openReader(page: Page, wiki: WikiFactory, telemetry: object) {
	const space = await wiki.space({
		roles: [{ role: 'Guest', permission_level: 'Read' }],
		pages: [{ title: 'Telemetry Page' }],
	});
	const route = space.page('Telemetry Page').route;

	await page.route(PULSE_CLIENT_URL, (request) =>
		request.fulfill({
			contentType: 'text/javascript',
			headers: { 'Access-Control-Allow-Origin': '*' },
			body: STUB_CLIENT,
		}),
	);
	await page.route(
		'**/api/method/wiki.frappe_wiki.doctype.wiki_document.wiki_document.download_pdf?*',
		(request) =>
			request.fulfill({ contentType: 'application/pdf', body: '%PDF-1.4' }),
	);

	// CI serves plain http on a non-localhost host, which has no navigator.clipboard.
	await page.addInitScript(() => {
		Object.defineProperty(navigator, 'clipboard', {
			value: { writeText: async () => {} },
		});
	});
	await page.goto(`/${route}`);
	await expect(page.locator('#wiki-page-title')).toBeVisible();

	// Overrides whatever Pulse config this site has. The binding is const, its object is not.
	await page.evaluate(
		(config) => Object.assign(readerTelemetry, config),
		telemetry,
	);

	// Keep the Ask AI links from leaving for chatgpt.com / claude.ai.
	await page.evaluate(() => {
		document.addEventListener(
			'click',
			(event) => {
				const anchor = (event.target as HTMLElement)?.closest?.(
					'a[target="_blank"]',
				);
				if (anchor) event.preventDefault();
			},
			true,
		);
	});
}

async function pickPageAction(
	page: Page,
	{ text, closesMenu }: (typeof ACTIONS)[number],
) {
	// The desktop menu beside the title; the mobile copy above it is hidden by CSS.
	const menu = page.locator('#wiki-page-title + div');
	const toggle = menu.getByRole('button', { name: 'More page actions' });
	if ((await toggle.getAttribute('aria-expanded')) !== 'true')
		await toggle.click();
	await expect(toggle).toHaveAttribute('aria-expanded', 'true');
	await menu.locator('a, button').filter({ hasText: text }).click();
	// Download closes the menu only once the PDF arrives, so wait it out.
	await expect(toggle).toHaveAttribute('aria-expanded', String(!closesMenu));
}

const ACTIONS = [
	{ text: 'Download', action: 'download', closesMenu: true },
	{ text: 'Copy page', action: 'copy', closesMenu: true },
	{ text: 'Open in ChatGPT', action: 'chatgpt', closesMenu: false },
	{ text: 'Open in Claude', action: 'claude', closesMenu: false },
];

test.describe('Page actions telemetry', () => {
	test('each menu item reports page_action_used through the Pulse client', async ({
		page,
		wiki,
	}) => {
		await openReader(page, wiki, {
			enabled: true,
			client_url: PULSE_CLIENT_URL,
			host: 'https://pulse.test',
			key: 'test-key',
			site: 'wiki.test',
			user: null,
			team: 'team-test',
			app_version: '9.9.9',
		});

		for (const item of ACTIONS) {
			await pickPageAction(page, item);
			await expect
				.poll(() =>
					page.evaluate(() => window.pulseEvents?.at(-1)?.props.action),
				)
				.toBe(item.action);
		}

		const events = await page.evaluate(() => window.pulseEvents);
		expect(events).toEqual(
			ACTIONS.map(({ action }) => ({
				event: 'page_action_used',
				app: 'wiki',
				props: { action, app_version: '9.9.9' },
			})),
		);
		expect(await page.evaluate(() => window.pulseOptions)).toEqual({
			host: 'https://pulse.test',
			apiKey: 'test-key',
			site: 'wiki.test',
			user: null,
			team: 'team-test',
			enabled: true,
		});
	});

	test('loads no Pulse client when telemetry is off', async ({
		page,
		wiki,
	}) => {
		await openReader(page, wiki, { enabled: false });
		const scriptRequests: string[] = [];
		page.on('request', (request) => {
			if (request.resourceType() === 'script')
				scriptRequests.push(request.url());
		});

		for (const item of ACTIONS) {
			await pickPageAction(page, item);
		}
		await page.waitForTimeout(500);

		expect(scriptRequests).toEqual([]);
		expect(await page.evaluate(() => window.pulseEvents)).toBeUndefined();
	});
});

import type { Page } from '@playwright/test';
import { expect, test } from '../fixtures';

function recordApiCalls(page: Page) {
	const calls: string[] = [];
	page.on('request', (request) => {
		const url = request.url();
		if (url.includes('/api/')) calls.push(url);
	});
	return calls;
}

test.describe('Space bootstrap', () => {
	test('opening a space loads the user, the space and the draft in one request', async ({
		page,
		wiki,
	}) => {
		const space = await wiki.space({ pages: [{ title: 'Alpha' }] });
		const calls = recordApiCalls(page);

		await page.goto(space.url());
		await expect(
			page.locator('aside').getByText('Alpha', { exact: true }),
		).toBeVisible({ timeout: 15000 });
		await expect(
			page.locator('.ProseMirror[contenteditable="true"]'),
		).toBeVisible();

		const called = (name: string) => calls.filter((url) => url.includes(name));
		expect(called('get_space_bootstrap')).toHaveLength(1);
		expect(called('get_user_info')).toEqual([]);
		expect(called('get_space_capabilities')).toEqual([]);
		expect(called('get_or_create_draft_change_request')).toEqual([]);
		expect(called('doctype=Wiki+Space&')).toEqual([]);
	});
});

import { expect, test } from '../fixtures';
import { getList } from '../helpers/frappe';
import { CHANGE_REQUEST_URL_RE } from '../helpers/routes';
import {
	clickSidebarAddOption,
	currentDraftDocKey,
	openNewPageDialog,
	publishChangeRequestFromReview,
	saveEditor,
} from '../helpers/wiki';

interface WikiDocumentRoute {
	route: string;
	doc_key: string;
}

declare global {
	interface Window {
		wikiEditor: {
			commands: {
				setContent: (
					content: string,
					options?: { contentType?: string },
				) => void;
			};
		};
	}
}

/**
 * Regression test for #699.
 *
 * The "Open in ChatGPT/Claude" page action bound its href once at render time
 * via Alpine's `:href`. `window.location` is not reactive, and SPA sidebar
 * navigation only refreshes the content/title/edit-links — never the AI links.
 * So after navigating from page A to page B the link still pointed at page A
 * until a full reload. The fix recomputes the href on click. This test drives
 * the real path: navigate A -> B via the sidebar, then assert the AI link
 * encodes page B's URL, not page A's.
 */
test.describe('Page actions – AI link URL', () => {
	test('Open in ChatGPT uses the current page URL after sidebar navigation', async ({
		page,
		request,
		wiki,
	}) => {
		await page.setViewportSize({ width: 1100, height: 900 });

		const space = await wiki.space({
			roles: [{ role: 'Guest', permission_level: 'Read' }],
		});
		await page.goto(space.url());
		await page.waitForLoadState('networkidle');

		const editor = page.locator('.ProseMirror, [contenteditable="true"]');

		// --- Create and fill the first page ---
		const firstPageTitle = `ai-url-first-${Date.now()}`;
		await openNewPageDialog(page);
		await page.getByLabel('Title').fill(firstPageTitle);
		await page
			.getByRole('dialog')
			.getByRole('button', { name: 'Save' })
			.click();
		await page.waitForLoadState('networkidle');

		await page
			.locator('aside')
			.getByText(firstPageTitle, { exact: true })
			.click();
		const firstDocKey = await currentDraftDocKey(page);
		expect(firstDocKey).not.toBe('');

		await expect(editor).toBeVisible({ timeout: 10000 });
		await page.waitForFunction(() => window.wikiEditor !== undefined, {
			timeout: 10000,
		});
		await page.evaluate(() => {
			window.wikiEditor.commands.setContent('First page body.', {
				contentType: 'markdown',
			});
		});
		await editor.click();
		await page.waitForTimeout(500);
		await saveEditor(page);
		await page.waitForLoadState('networkidle');
		await page.waitForTimeout(2000);

		// --- Create and fill the second page ---
		const secondPageTitle = `ai-url-second-${Date.now()}`;
		await clickSidebarAddOption(page, 'New Page');
		await page.getByLabel('Title').fill(secondPageTitle);
		await page
			.getByRole('dialog')
			.getByRole('button', { name: 'Save' })
			.click();
		await page.waitForLoadState('networkidle');

		await page
			.locator('aside')
			.getByText(secondPageTitle, { exact: true })
			.click();
		const secondDocKey = await currentDraftDocKey(page);
		expect(secondDocKey).not.toBe('');

		await expect(editor).toBeVisible({ timeout: 10000 });
		await page.waitForFunction(
			() => window.wikiEditor?.commands?.setContent !== undefined,
			{ timeout: 10000 },
		);
		await page.waitForTimeout(500);
		await page.evaluate(() => {
			window.wikiEditor.commands.setContent('Second page body.', {
				contentType: 'markdown',
			});
		});
		await editor.click();
		await page.waitForTimeout(500);
		await saveEditor(page);
		await page.waitForLoadState('networkidle');
		await page.waitForTimeout(2000);

		// --- Submit for review and publish both pages ---
		await page.getByRole('button', { name: 'Submit for Review' }).click();
		await page.getByRole('button', { name: 'Submit' }).click();
		await expect(page).toHaveURL(CHANGE_REQUEST_URL_RE, {
			timeout: 10000,
		});
		await publishChangeRequestFromReview(page);

		// --- Resolve public routes ---
		const [firstRoutes, secondRoutes] = await Promise.all([
			getList<WikiDocumentRoute>(request, 'Wiki Document', {
				fields: ['route', 'doc_key'],
				filters: { doc_key: firstDocKey },
				limit: 1,
			}),
			getList<WikiDocumentRoute>(request, 'Wiki Document', {
				fields: ['route', 'doc_key'],
				filters: { doc_key: secondDocKey },
				limit: 1,
			}),
		]);
		expect(firstRoutes.length).toBe(1);
		expect(secondRoutes.length).toBe(1);
		const firstRoute = firstRoutes[0].route;
		const secondRoute = secondRoutes[0].route;

		// --- Open first public page, then SPA-navigate to the second via sidebar ---
		const publicPage = await page.context().newPage();
		await publicPage.setViewportSize({ width: 1100, height: 900 });
		await publicPage.goto(`/${firstRoute}`);
		await publicPage.waitForLoadState('networkidle');

		const secondPageLink = publicPage
			.locator('.wiki-sidebar')
			.locator(`.wiki-link:has-text("${secondPageTitle}")`);
		await expect(secondPageLink).toBeVisible({ timeout: 5000 });
		await secondPageLink.click();

		// SPA navigation done: title (and URL) now reflect the second page.
		await expect(publicPage.locator('#wiki-page-title')).toHaveText(
			secondPageTitle,
			{ timeout: 10000 },
		);
		expect(publicPage.url()).toContain(`/${secondRoute}`);

		// Block the AI link from actually opening chatgpt.com (no external network
		// in CI). The capture-phase preventDefault stops the browser navigation but
		// still lets Alpine's @click handler run and recompute the href.
		await publicPage.evaluate(() => {
			document.addEventListener(
				'click',
				(e) => {
					const anchor = (e.target as HTMLElement)?.closest?.(
						'a[target="_blank"]',
					);
					if (anchor) e.preventDefault();
				},
				true,
			);
		});

		// Open the page-actions dropdown (toggle button sits next to the edit link).
		const editLink = publicPage.locator('a.wiki-edit-link:visible');
		await expect(editLink).toBeVisible({ timeout: 5000 });
		await editLink.locator('xpath=following-sibling::button').click();

		const aiLink = publicPage.locator('a:has-text("Open in ChatGPT"):visible');
		await expect(aiLink).toBeVisible({ timeout: 5000 });
		await aiLink.click();

		const decodedHref = decodeURIComponent(
			(await aiLink.getAttribute('href')) ?? '',
		);
		// The prompt must reference the current (second) page, not the first.
		expect(decodedHref).toContain(`/${secondRoute}`);
		expect(decodedHref).not.toContain(`/${firstRoute}`);

		await publicPage.close();
	});
});

